// And groups predicates with the AND operator between them.
func And(predicates ...predicate.HostedSession) predicate.HostedSession {
	return predicate.HostedSession(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.HostedSession) predicate.HostedSession {
	return predicate.HostedSession(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.HostedSession) predicate.HostedSession {
	return predicate.HostedSession(sql.NotPredicates(p))
}
